// Extract from HA state_changed event
const event = msg.payload.event || msg.payload;
const newState = event.new_state || {};
const entityId = newState.entity_id || event.entity_id || '';
const attrs = newState.attributes || {};

// Map entity_id → sender
let sender = null;
if (entityId === 'light.caia') sender = 'caia';
else if (entityId === 'light.lyra') sender = 'lyra';
else {
    node.warn('Unexpected entity: ' + entityId);
    return null;
}

// Build payload
const out = {
    sender: sender,
    rgb: attrs.rgb_color || null,                       // [r, g, b] or null
    brightness: (typeof attrs.brightness === 'number') ? attrs.brightness : null,
    color_temp: attrs.color_temp_kelvin || null,        // kelvin if in CT mode
    state: newState.state || 'unknown',                 // 'on' | 'off'
    ts: newState.last_updated || new Date().toISOString()
};

msg.payload = out;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
